CREATE TABLE people(id UUID PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), code TEXT NOT NULL, withdrawn_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE session_participants(id UUID PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, person_id UUID REFERENCES people(id), code TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES users(id), withdrawn_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(session_id,code), UNIQUE(id,session_id));
CREATE TABLE consent_records(id UUID PRIMARY KEY, participant_id UUID NOT NULL REFERENCES session_participants(id) ON DELETE CASCADE, status TEXT NOT NULL CHECK(status IN ('documented','withdrawn','not documented')), training_allowed BOOLEAN NOT NULL, recorded_by TEXT NOT NULL, source TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE speaker_mappings(id UUID PRIMARY KEY, participant_id UUID NOT NULL, session_id TEXT NOT NULL, speaker_id TEXT, revision INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('confirmed','uncertain','unmapped')), reviewer_id TEXT NOT NULL, reason TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), FOREIGN KEY(participant_id,session_id) REFERENCES session_participants(id,session_id) ON DELETE CASCADE, FOREIGN KEY(speaker_id,session_id) REFERENCES speakers(id,session_id), UNIQUE(participant_id,revision), CHECK(status!='confirmed' OR speaker_id IS NOT NULL));
CREATE TABLE form_definitions(id TEXT PRIMARY KEY, version TEXT NOT NULL, title TEXT NOT NULL, source_hash TEXT NOT NULL, definition JSONB NOT NULL);
CREATE TABLE form_items(form_id TEXT REFERENCES form_definitions(id), key TEXT NOT NULL, description TEXT NOT NULL, answer_type TEXT NOT NULL, allowed_values JSONB NOT NULL, modality TEXT NOT NULL, requirements JSONB NOT NULL, PRIMARY KEY(form_id,key));
CREATE TABLE annotation_imports(id UUID PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, owner_id TEXT NOT NULL REFERENCES users(id), filename TEXT NOT NULL, sha256 TEXT NOT NULL, source_bytes BYTEA NOT NULL CHECK(octet_length(source_bytes)<=10485760), media_type TEXT NOT NULL, mapping JSONB NOT NULL, preview JSONB NOT NULL, status TEXT NOT NULL DEFAULT 'preview', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(session_id,sha256,mapping));
CREATE TABLE annotation_import_rows(import_id UUID REFERENCES annotation_imports(id) ON DELETE CASCADE, row_number INTEGER NOT NULL, participant_id UUID REFERENCES session_participants(id) ON DELETE CASCADE, data JSONB NOT NULL, PRIMARY KEY(import_id,row_number));
CREATE TABLE annotation_submissions(id UUID PRIMARY KEY, participant_id UUID NOT NULL REFERENCES session_participants(id) ON DELETE CASCADE, form_id TEXT NOT NULL REFERENCES form_definitions(id), import_id UUID REFERENCES annotation_imports(id) ON DELETE CASCADE, source_type TEXT NOT NULL CHECK(source_type IN ('observer','self_report','independent_review')), reviewer_id TEXT, uploader_id TEXT NOT NULL REFERENCES users(id), revision INTEGER NOT NULL, supersedes UUID REFERENCES annotation_submissions(id) ON DELETE CASCADE, correction_reason TEXT NOT NULL, metadata JSONB NOT NULL, raw JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(participant_id,form_id,source_type,reviewer_id,revision));
CREATE TABLE annotation_answers(id UUID PRIMARY KEY, submission_id UUID NOT NULL REFERENCES annotation_submissions(id) ON DELETE CASCADE, item_key TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('scored','not_observed','missing')), score INTEGER CHECK(score BETWEEN 0 AND 4), fair_opportunity BOOLEAN, confidence INTEGER CHECK(confidence BETWEEN 1 AND 3), missing_reason TEXT NOT NULL, narrative TEXT NOT NULL, component TEXT NOT NULL DEFAULT 'audio', UNIQUE(submission_id,item_key), CHECK((state='scored')=(score IS NOT NULL)));
CREATE TABLE annotation_context_flags(submission_id UUID REFERENCES annotation_submissions(id) ON DELETE CASCADE, name TEXT NOT NULL, present BOOLEAN NOT NULL, notes TEXT NOT NULL, PRIMARY KEY(submission_id,name));
CREATE TABLE annotation_validity_checks(submission_id UUID REFERENCES annotation_submissions(id) ON DELETE CASCADE, name TEXT NOT NULL, category TEXT NOT NULL, explanation TEXT NOT NULL, PRIMARY KEY(submission_id,name));
CREATE TABLE annotation_pattern_summaries(submission_id UUID REFERENCES annotation_submissions(id) ON DELETE CASCADE, name TEXT NOT NULL, category TEXT NOT NULL CHECK(category IN ('Observed','Not clear','N/O')), confidence INTEGER CHECK(confidence BETWEEN 1 AND 3), narrative TEXT NOT NULL, PRIMARY KEY(submission_id,name));
CREATE TABLE annotation_evidence(id UUID PRIMARY KEY, answer_id UUID NOT NULL REFERENCES annotation_answers(id) ON DELETE CASCADE, evidence_id TEXT REFERENCES evidence(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK(kind IN ('support','event','response','same_session_baseline')), start_s DOUBLE PRECISION NOT NULL, end_s DOUBLE PRECISION NOT NULL, context TEXT NOT NULL, response TEXT NOT NULL, participation_effect TEXT NOT NULL, CHECK(start_s>=0 AND end_s>start_s));
CREATE TABLE annotation_reviews(id UUID PRIMARY KEY, submission_id UUID NOT NULL REFERENCES annotation_submissions(id) ON DELETE CASCADE, reviewer_id TEXT NOT NULL, decision TEXT NOT NULL CHECK(decision IN ('approved','rejected','needs_review')), notes TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE annotation_adjudications(id UUID PRIMARY KEY, answer_id UUID NOT NULL REFERENCES annotation_answers(id) ON DELETE CASCADE, reviewer_id TEXT NOT NULL, score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 4), rationale TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE annotation_attachments(id UUID PRIMARY KEY, submission_id UUID REFERENCES annotation_submissions(id) ON DELETE CASCADE, filename TEXT NOT NULL, media_type TEXT NOT NULL, sha256 TEXT NOT NULL, source_bytes BYTEA NOT NULL CHECK(octet_length(source_bytes)<=10485760));
CREATE FUNCTION immutable_annotation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Annotation history is immutable; submit a correction'; END $$;
CREATE TRIGGER immutable_answers BEFORE UPDATE ON annotation_answers FOR EACH ROW EXECUTE FUNCTION immutable_annotation();
CREATE TRIGGER immutable_submissions BEFORE UPDATE ON annotation_submissions FOR EACH ROW EXECUTE FUNCTION immutable_annotation();
CREATE TRIGGER immutable_mappings BEFORE UPDATE ON speaker_mappings FOR EACH ROW EXECUTE FUNCTION immutable_annotation();
CREATE TRIGGER immutable_reviews BEFORE UPDATE ON annotation_reviews FOR EACH ROW EXECUTE FUNCTION immutable_annotation();
